   22	func (a *API) updatePrefs(w http.ResponseWriter, r *http.Request) {
   23		u := auth.UserFrom(r.Context())
   24		var req struct {
   25			TZ        string `json:"tz"`
   26			Channel   string `json:"channel"`
   27			Webhook   string `json:"webhook"`
   28			QuietFrom string `json:"quiet_from"` // "22:00"
   29			QuietTo   string `json:"quiet_to"`
   30		}
   31		if !a.decode(w, r, &req) {
   32			return
   33		}
   34		p := *u.Prefs
   35		if req.TZ != "" {
   36			p.TZ = req.TZ
   37		}
   38		if req.Channel != "" {
   39			if !notify.ValidChannel(req.Channel) {
   40				a.fail(w, http.StatusBadRequest, "unknown channel "+strconv.Quote(req.Channel))
   41				return
   42			}
   43			p.Channel = req.Channel
   44		}
   45		if req.Webhook != "" {
   46			if hook, err := url.Parse(req.Webhook); err != nil || hook.Scheme != "https" {
   47				a.fail(w, http.StatusBadRequest, "webhook must be an https URL")
   48				return
   49			}
   50			p.Webhook = req.Webhook
   51		}
   52		for _, t := range []string{req.QuietFrom, req.QuietTo} {
   53			if t != "" && !clockPattern.MatchString(t) {
   54				a.fail(w, http.StatusBadRequest, "quiet hours must look like 22:00")
   55				return
   56			}
   57		}
   58		if req.QuietFrom != "" || req.QuietTo != "" {
   59			p.QuietFrom, p.QuietTo = req.QuietFrom, req.QuietTo
   60		}
   61		if err := a.Store.SetPrefs(u.ID, p); err != nil {
   62			a.writeError(w, err)
   63			return
   64		}
   65		a.writeJSON(w, http.StatusOK, p)
   66	}
