   70	func (a *API) digest(w http.ResponseWriter, r *http.Request) {
   71		u := auth.UserFrom(r.Context())
   72		days := 7
   73		if s := r.URL.Query().Get("days"); s != "" {
   74			n, err := strconv.Atoi(s)
   75			if err != nil || n < 1 || n > 31 {
   76				a.fail(w, http.StatusBadRequest, "days must be between 1 and 31")
   77				return
   78			}
   79			days = n
   80		}
   81		loc := must.Get(time.LoadLocation(u.Prefs.TZ))
   82		from := a.Now()
   83		occ := a.Store.Upcoming(u.ID, from, from.AddDate(0, 0, days))
   84		d := notify.BuildDigest(from, days, loc, occ)
   85		if u.Prefs.QuietFrom != "" && u.Prefs.QuietTo != "" {
   86			d.QuietHours = notify.QuietHours(u.Prefs.QuietFrom, u.Prefs.QuietTo)
   87		}
   88		a.writeJSON(w, http.StatusOK, d)
   89	}
